package com.metaverse.coin.strategy.core.arbitrage.multi;
import org.junit.jupiter.api.Test; import java.math.BigDecimal; import java.time.*; import java.util.*; import static org.junit.jupiter.api.Assertions.*;
class CrossExchangePositionMonitorServiceTest {
 @Test void closesWhenFundingSpreadFallsBelowExitThreshold(){Instant now=Instant.now();var executor=new PaperAtomicHedgeExecutor(new PaperPerpetualGateway());var risk=new CrossExchangeRiskService(new CrossExchangeRiskService.Limits(new BigDecimal("1000"),Duration.ofSeconds(5),Duration.ofDays(7),new BigDecimal("0.00001")));var paper=new CrossExchangePaperTradingService(executor,risk);var opened=paper.open(opportunity(now),new BigDecimal("100"),now);var monitor=new CrossExchangePositionMonitorService(List.of(provider(Exchange.BINANCE,"0.0001",now),provider(Exchange.OKX,"0.0001",now)),risk,paper);assertEquals(1,monitor.monitor(now.plusSeconds(1)).size());assertEquals(PaperHedgePosition.Status.CLOSED,executor.positions().get(opened.positionId()).status());}
 @Test void exitsWhenFundingSpreadCannotCoverRemainingCloseCosts(){Instant now=Instant.now();var executor=new PaperAtomicHedgeExecutor(new PaperPerpetualGateway());var risk=new CrossExchangeRiskService(new CrossExchangeRiskService.Limits(new BigDecimal("1000"),Duration.ofSeconds(5),Duration.ofDays(7),BigDecimal.ZERO));var paper=new CrossExchangePaperTradingService(executor,risk);paper.open(opportunity(now),new BigDecimal("100"),now);var cost=new ExchangeCost(BigDecimal.ZERO,new BigDecimal("0.00005"),BigDecimal.ZERO);var monitor=new CrossExchangePositionMonitorService(List.of(provider(Exchange.BINANCE,"0.0000",now),provider(Exchange.OKX,"0.0004",now)),risk,paper,null,Map.of(Exchange.BINANCE,cost,Exchange.OKX,cost),new BigDecimal("0.00001"));assertEquals(1,monitor.monitor(now.plusSeconds(1)).size());}
 @Test void automaticCloseUsesLatestMarks(){Instant now=Instant.now();var gateway=new PaperPerpetualGateway();var executor=new PaperAtomicHedgeExecutor(gateway);var risk=new CrossExchangeRiskService(new CrossExchangeRiskService.Limits(new BigDecimal("1000"),Duration.ofSeconds(5),Duration.ofDays(7),new BigDecimal("0.00001")));var paper=new CrossExchangePaperTradingService(executor,risk);var opened=paper.open(opportunity(now),new BigDecimal("100"),now);var monitor=new CrossExchangePositionMonitorService(List.of(provider(Exchange.BINANCE,"0.0001",now,"95"),provider(Exchange.OKX,"0.0001",now,"106")),risk,paper);monitor.monitor(now.plusSeconds(1));assertEquals(0,new BigDecimal("95").compareTo(closeOrder(gateway,opened.positionId(),"L").averagePrice()));assertEquals(0,new BigDecimal("106").compareTo(closeOrder(gateway,opened.positionId(),"S").averagePrice()));}
 @Test void manualCloseUsesLatestMarks(){Instant now=Instant.now();var gateway=new PaperPerpetualGateway();var executor=new PaperAtomicHedgeExecutor(gateway);var risk=new CrossExchangeRiskService(new CrossExchangeRiskService.Limits(new BigDecimal("1000"),Duration.ofSeconds(5),Duration.ofDays(7),BigDecimal.ZERO));var paper=new CrossExchangePaperTradingService(executor,risk);var opened=paper.open(opportunity(now),new BigDecimal("100"),now);var monitor=new CrossExchangePositionMonitorService(List.of(provider(Exchange.BINANCE,"0.001",now,"96"),provider(Exchange.OKX,"0.002",now,"107")),risk,paper);monitor.closeAtLatest(opened.positionId(),now.plusSeconds(1));assertEquals(0,new BigDecimal("96").compareTo(closeOrder(gateway,opened.positionId(),"L").averagePrice()));assertEquals(0,new BigDecimal("107").compareTo(closeOrder(gateway,opened.positionId(),"S").averagePrice()));}
 @Test void unavailableQuoteOpensCircuitWithoutFakeClose(){Instant now=Instant.now();var gateway=new PaperPerpetualGateway();var executor=new PaperAtomicHedgeExecutor(gateway);var risk=new CrossExchangeRiskService(new CrossExchangeRiskService.Limits(new BigDecimal("1000"),Duration.ofSeconds(5),Duration.ofDays(7),BigDecimal.ZERO));var paper=new CrossExchangePaperTradingService(executor,risk);var opened=paper.open(opportunity(now),new BigDecimal("100"),now);var monitor=new CrossExchangePositionMonitorService(List.of(failingProvider(Exchange.BINANCE),provider(Exchange.OKX,"0.002",now)),risk,paper);assertTrue(monitor.monitor(now.plusSeconds(1)).isEmpty());assertTrue(paper.isCircuitOpen());assertEquals(PaperHedgePosition.Status.OPENED,executor.positions().get(opened.positionId()).status());assertTrue(gateway.orders().stream().noneMatch(order->order.clientOrderId().contains("-CLOSE-")));}
 @Test void staleQuoteOpensCircuitWithoutFakeClose(){Instant now=Instant.now();var gateway=new PaperPerpetualGateway();var executor=new PaperAtomicHedgeExecutor(gateway);var risk=new CrossExchangeRiskService(new CrossExchangeRiskService.Limits(new BigDecimal("1000"),Duration.ofSeconds(5),Duration.ofDays(7),BigDecimal.ZERO));var paper=new CrossExchangePaperTradingService(executor,risk);paper.open(opportunity(now),new BigDecimal("100"),now);var monitor=new CrossExchangePositionMonitorService(List.of(provider(Exchange.BINANCE,"0.001",now),provider(Exchange.OKX,"0.002",now)),risk,paper,null,Map.of(),BigDecimal.ZERO,Duration.ofSeconds(30));assertTrue(monitor.monitor(now.plusSeconds(31)).isEmpty());assertTrue(paper.isCircuitOpen());assertTrue(gateway.orders().stream().noneMatch(order->order.clientOrderId().contains("-CLOSE-")));}
 @Test void closesWhenLatestFundingSettlementsDriftApart(){Instant now=Instant.now();var gateway=new PaperPerpetualGateway();var executor=new PaperAtomicHedgeExecutor(gateway);var risk=new CrossExchangeRiskService(new CrossExchangeRiskService.Limits(new BigDecimal("1000"),Duration.ofSeconds(5),Duration.ofDays(7),BigDecimal.ZERO));var paper=new CrossExchangePaperTradingService(executor,risk);var opened=paper.open(opportunity(now),new BigDecimal("100"),now);var monitor=new CrossExchangePositionMonitorService(List.of(provider(Exchange.BINANCE,"-0.001",now,now.plusSeconds(3600)),provider(Exchange.OKX,"0.001",now,now.plusSeconds(3961))),risk,paper,null,Map.of(),BigDecimal.ZERO,Duration.ofSeconds(30),Duration.ofMinutes(5));assertEquals(1,monitor.monitor(now.plusSeconds(1)).size());assertEquals(PaperHedgePosition.Status.CLOSED,executor.positions().get(opened.positionId()).status());}
 @Test void opensCircuitWhenManualInterventionExceedsNakedTimeout(){Instant now=Instant.now();var gateway=new PaperPerpetualGateway();gateway.scriptNext("-OPEN-S",PaperOrder.Status.TIMED_OUT,BigDecimal.ZERO);gateway.scriptNext("-COMPENSATE-L",PaperOrder.Status.REJECTED,BigDecimal.ZERO);var executor=new PaperAtomicHedgeExecutor(gateway);var risk=new CrossExchangeRiskService(new CrossExchangeRiskService.Limits(new BigDecimal("1000"),Duration.ofSeconds(5),Duration.ofDays(7),BigDecimal.ZERO));var paper=new CrossExchangePaperTradingService(executor,risk);var naked=paper.open(opportunity(now),new BigDecimal("100"),now);assertEquals(PaperHedgePosition.Status.MANUAL_INTERVENTION,naked.status());var monitor=new CrossExchangePositionMonitorService(List.of(),risk,paper);monitor.monitor(now.plusSeconds(5));assertTrue(paper.isCircuitOpen());}
 private CrossExchangeMarketDataProvider provider(Exchange e,String rate,Instant n){return new CrossExchangeMarketDataProvider(){public Exchange exchange(){return e;}public List<String> supportedUsdtPerpetualSymbols(){return List.of("BTCUSDT");}public NormalizedFundingRateSnapshot fundingRate(String s){return new NormalizedFundingRateSnapshot(e,s,new BigDecimal(rate),8,n.plusSeconds(3600),new BigDecimal("100"),new BigDecimal("100"),n);}public NormalizedOrderBookSnapshot orderBook(String s,int d){return null;}};}
 private CrossExchangeMarketDataProvider provider(Exchange e,String rate,Instant n,String mark){return new CrossExchangeMarketDataProvider(){public Exchange exchange(){return e;}public List<String> supportedUsdtPerpetualSymbols(){return List.of("BTCUSDT");}public NormalizedFundingRateSnapshot fundingRate(String s){return new NormalizedFundingRateSnapshot(e,s,new BigDecimal(rate),8,n.plusSeconds(3600),new BigDecimal(mark),new BigDecimal(mark),n);}public NormalizedOrderBookSnapshot orderBook(String s,int d){return null;}};}
 private CrossExchangeMarketDataProvider provider(Exchange e,String rate,Instant n,Instant settlement){return new CrossExchangeMarketDataProvider(){public Exchange exchange(){return e;}public List<String> supportedUsdtPerpetualSymbols(){return List.of("BTCUSDT");}public NormalizedFundingRateSnapshot fundingRate(String s){return new NormalizedFundingRateSnapshot(e,s,new BigDecimal(rate),8,settlement,new BigDecimal("100"),new BigDecimal("100"),n);}public NormalizedOrderBookSnapshot orderBook(String s,int d){return null;}};}
 private CrossExchangeMarketDataProvider failingProvider(Exchange e){return new CrossExchangeMarketDataProvider(){public Exchange exchange(){return e;}public List<String> supportedUsdtPerpetualSymbols(){return List.of("BTCUSDT");}public NormalizedFundingRateSnapshot fundingRate(String s){throw new IllegalStateException("unavailable");}public NormalizedOrderBookSnapshot orderBook(String s,int d){return null;}};}
 private PaperOrder closeOrder(PaperPerpetualGateway gateway,String positionId,String leg){return gateway.orders().stream().filter(order->order.clientOrderId().startsWith(positionId+"-ATTEMPT-")).filter(order->order.clientOrderId().contains("-CLOSE-")).filter(order->order.clientOrderId().endsWith("-"+leg)).findFirst().orElseThrow();}
 private CrossExchangeOpportunity opportunity(Instant n){var l=new NormalizedFundingRateSnapshot(Exchange.BINANCE,"BTCUSDT",new BigDecimal("-0.001"),8,n.plusSeconds(3600),new BigDecimal("100"),new BigDecimal("100"),n);var s=new NormalizedFundingRateSnapshot(Exchange.OKX,"BTCUSDT",new BigDecimal("0.001"),8,n.plusSeconds(3600),new BigDecimal("100"),new BigDecimal("100"),n);return new CrossExchangeOpportunity("x","BTCUSDT",l,s,new BigDecimal("0.00025"),new BigDecimal("0.0002"),new BigDecimal("100"),CrossExchangeOpportunity.Status.QUALIFIED,null,n);}
}
